vxe-header--column.col--last {
    background-image: none;
}
/* 表头有两行的压缩行高 */
.table_standard .vxe-header--column .vxe-cell--title {
    line-height: 20px;
}

/* 气泡宽度最大宽度定义 */
.popover_max_width_350.el-popover {
    max-width: 350px;
}
.popover_max_width_450.el-popover {
    max-width: 450px;
}
/* 气泡整体最大宽高定义 */
.popover_box_max.el-popover .popover_content {
    overflow: auto;
    max-width: 560px;
    max-height: 320px;
}

.translateZ_0 {
    -webkit-transform: translateZ(0);
    transform: translateZ(0);
}

.dialog_content_title {
    display: flex;
    align-items: center;
    height: 32px;
    margin-bottom: 12px;
    color: var(--main_color);
    font-size: 14px;
}

.dialog_content_title:before {
    content: '';
    display: inline-block;
    margin-right: 8px;
    width: 2px;
    height: 15px;
    border-radius: 1px;
    background: var(--warning_color);
}

.dialog_export_setting {
    position: relative;
    display: flex;
    align-items: center;
    height: 32px;
    margin-bottom: 12px;
    color: var(--main_color);
    font-size: 14px;
}

.dialog_export_setting:before {
    position: absolute;
    left: -8px;
    content: '';
    display: inline-block;
    width: 2px;
    height: 15px;
    border-radius: 1px;
    background: var(--warning_color);
}

/* 提醒气泡最大宽度 */
.popover_max_width_300.el-popover {
    max-width: 300px;
}

/* 列表复选框左右12px间距设置 */
.vxe-table.size--small .vxe-header--column.col--checkbox .vxe-cell,
.vxe-table.size--small .vxe-body--column.col--checkbox .vxe-cell {
    min-width: 30px;
    padding: 0 4px 0 12px;
}

/* el-input 错误信息隐藏不显示 */
.el_hidden_error_msg .el-form-item__error {
    display: none;
}
.el_hidden_error_msg.el-form-item {
    margin-bottom: 0;
}

.max_height_300.single_el_popover {
    max-height: 300px;
    overflow-y: auto;
}

.max_height_300.popover_content {
    max-height: 300px;
    overflow-y: auto;
}

/* 列表外链样式*/
.out_site_link {
    cursor: pointer;
}
.out_site_link:hover {
    text-decoration: underline;
}

.row--hover .out_site_link {
    color: var(--primary-default);
}

