# -*- coding: utf-8 -*-
"""
探清 ERP「手动更新」(获取跟踪号/更新订单状态) 操作：
三方仓视图 -> 工具栏【手动更新】-> 弹「提示：获取中…获取完成 共N包裹 已获取X 失败Y」-> 关闭。
不分渠道。此操作只拉取状态，不发货，安全。
"""
import sys, os, time
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import config, core, erp
from playwright.sync_api import sync_playwright


def main():
    with sync_playwright() as p:
        ctx = core.open_context(p)
        page = ctx.pages[0] if ctx.pages else ctx.new_page()
        if not core.ensure_erp(page):
            print("ERP 未登录（会话失效）"); ctx.close(); return
        erp.open_order_ship(page)

        # 切到三方仓视图
        for name in ["三方仓"]:
            try:
                page.click(f"text={name}", timeout=6000); time.sleep(3)
                print("已点", name)
            except Exception as e:
                print("点", name, "失败:", e)

        # dump 工具栏按钮
        btns = page.evaluate(r"""() => [...document.querySelectorAll('button, .el-button, .base_button_comp, [class*=btn]')]
            .filter(b=>b.offsetParent!==null)
            .map(b=>(b.innerText||'').trim().replace(/\s+/g,''))
            .filter(t=>t && t.length<=8)""")
        print("三方仓工具栏按钮:", sorted(set(btns)))

        # 定位【更新追踪】：列出所有文本含"更新追踪"的可见元素及其上下文
        cands = page.evaluate(r"""() => {
            const out=[];
            document.querySelectorAll('*').forEach(e=>{
                if(e.children.length>0) return;               // 叶子
                const t=(e.innerText||'').trim();
                if(t==='更新追踪' && e.offsetParent!==null){
                    const r=e.getBoundingClientRect();
                    out.push({tag:e.tagName, cls:(typeof e.className==='string'?e.className:'').slice(0,50),
                              inRow: !!e.closest('.vxe-body--row'),
